1.22.text:
// Exercise 1.22. Write a program that reads several transactions for the same ISBN. Write the sum of all transactions that were read.

#include <iostream>
#include "Sales_item.h"

int main()
{
    Sales_item items, newItem;

    int transCount = 0;
    std::cout << "Enter items: " << std::endl;
    if (!(std::cin >> items)) {
        std::cerr << "Invalid data";
        return -1;
    }
    ++transCount;
    while (std::cin >> newItem) {
// Note: ISBN check; will be introduced in the next section
        if (newItem.isbn() != items.isbn()) {
            std::cerr << "ISBN mismatch" << std::endl;
            return -1;
        }
        ++transCount;
    }
    std::cout << transCount << std::endl;
    return 0;
}

1.23.text:
// Exercise 1.23. Write a program that reads several transactions and counts how many transactions occur for each ISBN.

#include <iostream>
#include "Sales_item.h"

int main()
{
    Sales_item currItem, item;

    std::cout << "Enter transactions:" << std::endl;
    if (!(std::cin >> currItem)) {
        std::cerr << "Invalid data" << std::endl;
        return -1;
    }
    int count = 1;
    while (std::cin >> item)
        if (currItem.isbn() == item.isbn())
            count++;
        else {
            std::cout << currItem.isbn() << " " << count <<  std::endl;
            currItem = item;
            count = 1;
        }
    std::cout << currItem.isbn() << " " << count << std::endl;
    return 0;
}

