1.25.text:
// Exercise 1.25. Using the Sales_item.h header from the Web site, compile and execute the bookstore program presented in this section.

#include <iostream>
#include "Sales_item.h"

int main()
{
    Sales_item total;        // variable to hold data for the next transaction

    if (std::cin >> total) { //read first trans
        Sales_item trans;    // variable to hold the running sum;
        while (std::cin >> trans) {  // read and process the rest
            if (total.isbn() == trans.isbn())
                total+= trans;   // update the running total
            else {
                std::cout << total << std::endl;  // print previous book result
                total = trans;   // trans now refers to the next book
            }
        }
        std::cout << total << std::endl; // print the last transaction
    } else {
        std::cerr << "No data?!" << std::endl;
        return -1;
    }
    return 0;
}

